def rename(table, pairs, reverse=False):
    connection = op.get_bind()
    for source, target in pairs:
        if reverse:
            source, target = target, source
        connection.execute(text(f"UPDATE {table} SET name = :target WHERE name = :source AND NOT EXISTS (SELECT 1 FROM {table} WHERE lower(name) = lower(:target))"), {'source': source, 'target': target})


def translate_indications(reverse=False):
    connection = op.get_bind()
    for source, target in MAIN_INDICATIONS:
        if reverse:
            source, target = target, source
        connection.execute(text("UPDATE medicines SET main_indications = :target WHERE main_indications = :source"), {'source': source, 'target': target})


